    def __init__(self):
        # Stack stores pairs: (value, min_at_this_level)
        self.stack = []

    def push(self, val: int) -> None:
        if not self.stack:
            # First element - it's the minimum
            self.stack.append((val, val))
        else:
            # Store val along with current minimum
            current_min = min(val, self.stack[-1][1])
            self.stack.append((val, current_min))

    def pop(self) -> None:
        self.stack.pop()

    def top(self) -> int:
        return self.stack[-1][0]

    def getMin(self) -> int:
        return self.stack[-1][1]

